        private string GetMonthSalaryReportPath(int intMau)
        {
            if (intMau == 1)
                return "Report/Salary/BangLuong_Mau1_LuongNhanVien.repx";
            if (intMau == 2)
                return "Report/Salary/BangLuong_Mau2_LuongBaoVe.repx";
            return "Report/Salary/BangLuong_Mau3_BangKeChuyenKhoan.repx";
        }

        private string GetMonthSalaryExportFilePrefix(int intMau)
        {
            if (intMau == 1)
                return "Mau1_Luong_NhanVien";
            if (intMau == 2)
                return "Mau2_Luong_BaoVe";
            return "Mau3_BangKe_ChuyenKhoan";
        }

        private void SetMonthSalaryReportParameters(XtraReport report)
        {
            if (report == null)
                return;

            report.RequestParameters = false;
            SetXtraReportParameterValue(report, "pDepartment", lookupDepartmentID.Text);
            SetXtraReportParameterValue(report, "pMonth", dtmDate);
            SetXtraReportParameterValue(report, "par_THANG", dtmDate.Month);
            SetXtraReportParameterValue(report, "par_NAM", dtmDate.Year);
            SetXtraReportParameterValue(report, "par_NOW", DateTime.Now.ToString("dd/MM/yyyy"));
        }

        private void SetXtraReportParameterValue(XtraReport report, string strName, object objValue)
        {
            if (report == null || string.IsNullOrEmpty(strName))
                return;

            DevExpress.XtraReports.Parameters.Parameter param = report.Parameters[strName];
            if (param != null)
                param.Value = objValue;
        }

        private XtraReport CreateMonthSalaryXtraReport(int intMau, DataTable dtbSource)
        {
            string strReportRel = GetMonthSalaryReportPath(intMau);
            string strReportPath = Path.Combine(Application.StartupPath, strReportRel.Replace('/', Path.DirectorySeparatorChar));
            if (!File.Exists(strReportPath))
            {
                ErrorManager.Error("Không tìm thấy mẫu in: " + strReportPath);
                return null;
            }

            XtraReport report = new XtraReport();
            report.LoadLayout(strReportPath);
            report.DataSource = dtbSource;
            SetMonthSalaryReportParameters(report);
            return report;
        }

        private void PrintMonthSalary(int intMau)
        {
            DataTable dtbPrint = PrepareMonthSalaryOutputData(intMau);
            if (dtbPrint == null || dtbPrint.Rows.Count == 0)
            {
                if (intMau == 3)
                    MessageManager.Warning("Bạn phải tick chọn dữ liệu để in!");
                else
                    MessageManager.Warning("Không có dữ liệu phù hợp mẫu in đang chọn!");
                return;
            }

            string strReport = GetMonthSalaryReportPath(intMau);
            SystemManager.Report.frmReportView frm = new SystemManager.Report.frmReportView(dtbPrint, strReport, false);
            frm.SetParameter("pDepartment", lookupDepartmentID.Text);
            frm.SetParameter("pMonth", dtmDate);
            frm.SetParameter("par_THANG", dtmDate.Month);
            frm.SetParameter("par_NAM", dtmDate.Year);
            frm.SetParameter("par_NOW", DateTime.Now.ToString("dd/MM/yyyy"));
            frm.Show();
        }

        /// <summary>
        /// Xuất Excel từ cùng file .repx với in (DevExpress ExportToXls). Mẫu 1–3.
        /// </summary>
        private void ExportExcelMonthSalary(int intMau)
        {
            DataTable dtbExport = PrepareMonthSalaryOutputData(intMau);
            if (dtbExport == null || dtbExport.Rows.Count == 0)
            {
                if (intMau == 3)
                    MessageManager.Warning("Bạn phải tick chọn dữ liệu để xuất bảng kê chuyển khoản!");
                else if (dtbData == null || dtbData.Rows.Count == 0)
                    MessageManager.Warning("Không có dữ liệu để xuất!");
                else
                    MessageManager.Warning("Không có dữ liệu phù hợp mẫu excel đang chọn!");
                return;
            }

            string strSavePrefix = GetMonthSalaryExportFilePrefix(intMau);
            string strExportDir = Path.Combine(Application.StartupPath, "Export");
            if (!Directory.Exists(strExportDir))
                Directory.CreateDirectory(strExportDir);

            string timeStamp = DateTime.Now.ToString("yyyyMMdd_HHmmss");
            string strFileNamSaveAs = Path.Combine(strExportDir, timeStamp + "_" + strSavePrefix + ".xls");

            XtraReport report = null;
            Cursor objOldCursor = Cursor;
            try
            {
                Cursor = Cursors.WaitCursor;
                report = CreateMonthSalaryXtraReport(intMau, dtbExport);
                if (report == null)
                    return;

                report.CreateDocument();

                XlsExportOptions xlsOptions = new XlsExportOptions();
                xlsOptions.ShowGridLines = true;
                xlsOptions.ExportMode = XlsExportMode.SingleFile;
                report.ExportToXls(strFileNamSaveAs, xlsOptions);
            }
            catch (Exception)
            {
                ErrorManager.Error("Xuất excel thất bại!");
                return;
            }
            finally
            {
                if (report != null)
                    report.Dispose();
                Cursor = objOldCursor;
            }

            System.Diagnostics.Process.Start(strFileNamSaveAs);
        }

    }
}

